export function drawCarFire(ctx,x,y,width,time){if(time===null)return;ctx.save();for(let i=0;i<10;i++){const life=((time*.25+i*.177)%1+1)%1;ctx.fillStyle='rgba(31,28,26,'+((1-life)*.26)+')';ctx.beginPath();ctx.arc(x+Math.sin(i*2+time)*width*(.15+life*.2),y-width*(.45+life*1.8),width*(.15+life*.3),0,Math.PI*2);ctx.fill();}for(let i=0;i<9;i++){const left=x+(i/8-.5)*width*.8,base=y-width*.1,height=width*(.3+.28*(.5+.5*Math.sin(i*3.2+time*11)));const g=ctx.createLinearGradient(left,base,left,base-height);g.addColorStop(0,'#fff2a6ee');g.addColorStop(.35,'#ff991fe8');g.addColorStop(1,'#d72d0000');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(left-width*.10,base);ctx.quadraticCurveTo(left+Math.sin(time*9+i)*width*.12,base-height*.5,left,base-height);ctx.quadraticCurveTo(left+width*.15,base-height*.4,left+width*.1,base);ctx.fill();}ctx.restore();}
